"""Generate model completions for capability dataset prompts using vLLM."""

import argparse
import json
from pathlib import Path

from transformers import AutoTokenizer
from vllm import LLM, SamplingParams
from utils.load_data import load_raw_dataset


def parse_capability_datasets(raw: str) -> dict[str, str]:
    """Parse 'name1:path1,name2:path2,...' into a dict with autogenerated names."""
    result = {}
    for i, item in enumerate(raw.split(",")):
        if ":" in item:
            name, path = item.split(":", 1)
        else:
            name = f"capability_{i}"
            path = item
        result[name] = path.strip()
    return result


def extract_tools(sample: dict) -> list[dict]:
    """Extract tool definitions from a sample, if present."""
    tools = []
    if "tools" in sample:
        tools = sample["tools"]
    elif "tool_calls" in sample:
        # Some datasets might have a different structure for tools
        tools = sample["tool_calls"]

    return tools


def extract_messages(sample: dict) -> list[dict[str, str]]:
    """Extract conversation messages up to the last user message.

    Supports common dataset formats: 'messages' (OpenAI/HF), 'conversations'
    (ShareGPT), and 'prompt' (single-turn).
    """
    messages = None

    if "messages" in sample:
        # print("Found 'messages' key, using it for conversation.")
        messages = sample["messages"]
    elif "conversations" in sample:
        # print("Found 'conversations' key, using it for conversation with role mapping.")
        role_map = {"human": "user", "gpt": "assistant", "system": "system"}
        messages = [
            {"role": role_map.get(c["from"], c["from"]), "content": c["value"]}
            for c in sample["conversations"]
        ]
    elif "prompt" in sample:
        # Treat single prompt text as a single-turn user message.
        messages = [{"role": "user", "content": sample["prompt"]}]
    else:
        raise ValueError(
            f"Cannot extract messages from sample with keys: {list(sample.keys())}"
        )

    # Truncate after the last user message (drop trailing assistant turns)
    last_user_idx = -1
    for i, msg in enumerate(messages):
        if msg["role"] == "user":
            last_user_idx = i
    if last_user_idx == -1:
        raise ValueError("No user message found in sample")
    return messages[: last_user_idx + 1]


def add_assistant_message(
    messages: list[dict[str, str]], content: str
) -> list[dict[str, str]]:
    """Append an assistant message to the conversation."""
    return messages + [{"role": "assistant", "content": content}]


def decode_row_if_needed(row: dict) -> dict:
    """Decode loader fallback rows stored as raw JSON strings."""
    raw = row.get("__raw_json_row__")
    if isinstance(raw, str):
        parsed = json.loads(raw)
        if not isinstance(parsed, dict):
            raise ValueError(
                f"Expected decoded JSON row to be an object, got {type(parsed).__name__}"
            )
        return parsed
    return row


def generate_completions(args: argparse.Namespace) -> None:
    """Main logic: generate completions for each capability dataset using vLLM."""
    tokenizer = AutoTokenizer.from_pretrained(args.model, trust_remote_code=True)

    llm = LLM(
        model=args.model,
        dtype="bfloat16",
        max_model_len=args.max_seq_len,
        trust_remote_code=True,
        tensor_parallel_size=args.tensor_parallel_size,
        gpu_memory_utilization=args.gpu_memory_utilization,
    )

    if args.thinking:
        temperature = 0.6
        top_p = 0.95
        top_k = 20
        min_p = 0
    else:
        temperature = 0.7
        top_p = 0.8
        top_k = 20
        min_p = 0

    sampling_params = SamplingParams(
        max_tokens=args.max_new_tokens,
        temperature=temperature,
        top_p=top_p,
        top_k=top_k,
        min_p=min_p,
    )

    capability_datasets = parse_capability_datasets(args.capability_datasets)
    output_dir = Path(args.output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    if args.num_samples is None:
        num_samples = int(1e9)  # effectively no limit
    else:
        num_samples = args.num_samples

    for cap_name, cap_path in capability_datasets.items():
        print(f"Generating completions for: {cap_name}")

        # Load dataset
        ds = load_raw_dataset(cap_path, streaming=False, num_proc=32)
        ds = ds.shuffle(seed=42)  # Shuffle to get a random sample if needed

        column_names = set(ds.column_names or [])
        if "__raw_json_row__" in column_names and len(ds) > 0:
            first_decoded = decode_row_if_needed(ds[0])
            column_names = set(first_decoded.keys())

        # if "messages" or "conversations" or "prompt" not in dataset, assume text is under "text" or "content" keys. We do not need to generate, just return the text as the "completion"
        thinking_str = "think" if args.thinking else "no-think"
        output_file_text = output_dir / f"{cap_name}_{thinking_str}_text.jsonl"
        output_file_tokens = output_dir / f"{cap_name}_{thinking_str}_tokens.jsonl"

        if "text" in column_names or "content" in column_names:
            print(
                f"Dataset {cap_name} already has 'text'/'content' columns, skipping generation."
            )
            cntr = 0
            with open(output_file_text, "w") as f:
                for row in ds:
                    row = decode_row_if_needed(row)
                    text = row.get("text", row.get("content", str(row)))
                    f.write(
                        json.dumps(
                            {
                                "text": text,
                            }
                        )
                        + "\n"
                    )
                    cntr += 1
                    if cntr >= num_samples:
                        break

        elif (
            "messages" in column_names
            or "conversations" in column_names
            or "prompt" in column_names
        ):
            print(
                f"Dataset {cap_name} has conversation format, applying chat template for generation."
            )

            # Extract messages and apply chat template to get prompt strings
            prompts: list[str] = []
            max_prompt_tokens = args.max_seq_len - args.max_new_tokens
            cntr = 0
            ds = ds.shuffle(
                seed=42
            )  # Shuffle again to ensure randomness after decoding
            num_samples = min(num_samples, len(ds))
            ds = ds.select(range(num_samples))

            decoded_samples = [decode_row_if_needed(sample) for sample in ds.to_list()]
            messages_list = [extract_messages(sample) for sample in decoded_samples]
            tools_list = [extract_tools(sample) for sample in decoded_samples]
            prompt_ids_list = []
            # for sample in ds:
            for i in range(num_samples):
                messages = messages_list[i]
                tools = tools_list[i]
                # Tokenize first to enable proper truncation
                prompt_ids = tokenizer.apply_chat_template(
                    messages,
                    tools=tools,
                    tokenize=True,
                    add_generation_prompt=True,
                    max_length=max_prompt_tokens,
                    truncation=True,
                    enable_thinking=args.thinking,
                )
                prompt_ids_list.append(prompt_ids)
                # Decode back to text for vLLM
                prompt = tokenizer.decode(prompt_ids, skip_special_tokens=False)
                prompts.append(prompt)
                cntr += 1
                if cntr >= num_samples:
                    break

            # Generate all prompts at once — vLLM handles batching internally
            # Filter out empty prompts
            valid_indices = [i for i, p in enumerate(prompts) if p.strip()]
            if len(valid_indices) < len(prompts):
                print(
                    f"  Warning: {len(prompts) - len(valid_indices)} prompts were empty after truncation, skipping."
                )
                prompts = [prompts[i] for i in valid_indices]

            outputs = llm.generate(prompts, sampling_params)

            # Write results
            total_num_tokens = 0
            total_num_generated_tokens = 0

            # save one sample
            output = outputs[0]

            generated_text = output.outputs[0].text
            # append to the original prompt to get the full conversation
            full_conversation = add_assistant_message(messages_list[0], generated_text)
            with open(output_dir / f"{cap_name}_sample.txt", "w") as f:
                f.write(
                    json.dumps({"content": full_conversation, "tools": tools_list[0]})
                    + "\n"
                )

            with open(output_file_text, "w") as f:
                for i in range(num_samples):
                    output = outputs[i]

                    # save {"messages": full_conversation, "tools": tools_list[i]} for each sample
                    generated_text = output.outputs[0].text
                    # append to the original prompt to get the full conversation
                    full_conversation = add_assistant_message(
                        messages_list[i], generated_text
                    )
                    f.write(
                        json.dumps(
                            {"messages": full_conversation, "tools": tools_list[i]}
                        )
                        + "\n"
                    )

            with open(output_file_tokens, "w") as f:
                for i in range(num_samples):
                    output = outputs[i]
                    # save {"input_ids": ..., } for each sample
                    prompt_ids = prompt_ids_list[i]
                    generated_ids = output.outputs[0].token_ids
                    total_num_generated_tokens += len(generated_ids)
                    f.write(
                        json.dumps({"input_ids": prompt_ids + generated_ids}) + "\n"
                    )

            print(
                f"  Saved {len(outputs)} samples to {output_file_text}, {output_file_tokens}"
            )
            print(f"  Total new tokens generated: {total_num_generated_tokens}")
        else:
            raise ValueError(
                f"Dataset {cap_name} should have either 'messages', 'conversations', 'prompt' or 'text'/'content' columns."
            )

    # Save metadata
    metadata = {
        "model": args.model,
        "max_num_samples": args.num_samples,
        "max_new_tokens": args.max_new_tokens,
        "max_seq_len": args.max_seq_len,
        "temperature": temperature,
        "top_p": top_p,
        "top_k": top_k,
        "min_p": min_p,
        "capabilities": list(capability_datasets.keys()),
        "thinking": args.thinking,
        "total_num_tokens": total_num_tokens,
        "total_num_generated_tokens": total_num_generated_tokens,
    }
    with open(output_dir / "metadata_generate.json", "w") as f:
        json.dump(metadata, f, indent=2)

    print(f"Done. Output: {args.output_dir}")


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Generate model completions for capability dataset prompts."
    )
    parser.add_argument(
        "--model", type=str, required=True, help="HuggingFace model name or path"
    )
    parser.add_argument(
        "--capability_datasets",
        type=str,
        required=True,
        help="Mapping of capability:path pairs, comma-separated "
        "(e.g., chat:data/chat.jsonl,math:data/math.jsonl)",
    )
    parser.add_argument(
        "--num_samples",
        type=int,
        default=None,
        help="Number of samples per capability (default: 200)",
    )
    parser.add_argument(
        "--max_new_tokens",
        type=int,
        default=2048,
        help="Max tokens to generate per sample (default: 2048)",
    )
    parser.add_argument(
        "--max_seq_len",
        type=int,
        default=4096,
        help="Max total sequence length including prompt (default: 4096)",
    )
    parser.add_argument(
        "--tensor_parallel_size",
        type=int,
        default=1,
        help="Number of GPUs for tensor parallelism (default: 1)",
    )
    parser.add_argument(
        "--output_dir", type=str, required=True, help="Directory to save completions"
    )
    parser.add_argument(
        "--thinking",
        action="store_true",
        help="Whether to enable thinking mode in chat template",
    )
    parser.add_argument(
        "--gpu_memory_utilization",
        type=float,
        default=0.8,
        help="Target GPU memory utilization for vLLM (default: 0.8)",
    )

    args = parser.parse_args()
    generate_completions(args)


if __name__ == "__main__":
    main()
